// 工具函数
export function filterByMonthRange<T extends {month?:string;date?:string}>(
  data: T[], startMonth: string, endMonth: string
): T[] {
  return data.filter(d => {
    const key = d.month || d.date || '';
    return key >= startMonth && key <= endMonth;
  });
}

export function getIndexRange(monthsArr: string[], startMonth: string, endMonth: string): [number,number] {
  let startIdx = monthsArr.findIndex(m => m >= startMonth);
  let endIdx = monthsArr.findIndex(m => m > endMonth) - 1;
  if (startIdx === -1) startIdx = 0;
  if (endIdx < startIdx) endIdx = monthsArr.length - 1;
  return [startIdx, endIdx + 1];
}

export function sliceByRange(arr: number[], monthsArr: string[], startMonth: string, endMonth: string): number[] {
  const [s, e] = getIndexRange(monthsArr, startMonth, endMonth);
  return arr.slice(s, e);
}

